CREATE TABLE IF NOT EXISTS users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,role VARCHAR(10) NOT NULL CHECK(role IN ('BUYER','SELLER','ADMIN')),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,seller_id BIGINT NOT NULL REFERENCES users(id),name VARCHAR(180) NOT NULL,description CLOB,price DECIMAL(10,2) NOT NULL CHECK(price>0),stock_qty INT NOT NULL DEFAULT 0 CHECK(stock_qty>=0),category VARCHAR(30) NOT NULL,image_url VARCHAR(1000),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,buyer_id BIGINT NOT NULL REFERENCES users(id),status VARCHAR(15) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','CONFIRMED','SHIPPED','DELIVERED','CANCELLED')),total_amount DECIMAL(10,2) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id BIGINT NOT NULL REFERENCES orders(id),product_id BIGINT NOT NULL REFERENCES products(id),quantity INT NOT NULL,unit_price DECIMAL(10,2) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cart_items(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),product_id BIGINT NOT NULL REFERENCES products(id),quantity INT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT uq_cart UNIQUE(user_id,product_id));
CREATE TABLE IF NOT EXISTS reviews(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,product_id BIGINT NOT NULL REFERENCES products(id),user_id BIGINT NOT NULL REFERENCES users(id),rating INT NOT NULL CHECK(rating BETWEEN 1 AND 5),comment CLOB NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT uq_review UNIQUE(product_id,user_id));
CREATE TABLE IF NOT EXISTS wishlist(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),product_id BIGINT NOT NULL REFERENCES products(id),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT uq_wish UNIQUE(user_id,product_id));
CREATE INDEX IF NOT EXISTS idx_products_seller ON products(seller_id);CREATE INDEX IF NOT EXISTS idx_orders_buyer ON orders(buyer_id);CREATE INDEX IF NOT EXISTS idx_orders_status ON orders(status);CREATE INDEX IF NOT EXISTS idx_items_order ON order_items(order_id);CREATE INDEX IF NOT EXISTS idx_items_product ON order_items(product_id);CREATE INDEX IF NOT EXISTS idx_cart_user ON cart_items(user_id);CREATE INDEX IF NOT EXISTS idx_cart_product ON cart_items(product_id);CREATE INDEX IF NOT EXISTS idx_reviews_product ON reviews(product_id);CREATE INDEX IF NOT EXISTS idx_reviews_user ON reviews(user_id);CREATE INDEX IF NOT EXISTS idx_wishlist_user ON wishlist(user_id);CREATE INDEX IF NOT EXISTS idx_wishlist_product ON wishlist(product_id);